function getEkipRenk(uid,ekipList){const u=ekipList.find(x=>x.id===uid);if(!u)return null;if(u.renk)return u.renk;const idx=ekipList.indexOf(u);return EKIP_RENKLER[idx%EKIP_RENKLER.length];}
const EKIP_RENKLER=["#0d47a1","#c62828","#2e7d32","#e65100","#6a1b9a","#00838f","#4e342e","#f59e0b"];
const C={pri:"#0d47a1",onPri:"#fff",priC:"#d1e4ff",onPriC:"#001d36",secC:"#d8e3f8",onSecC:"#111c2b",err:"#b3261e",errC:"#ffdad6",surf:"#f7f9ff",surfLow:"#eff2fa",surfCont:"#e8ebf4",surfHi:"#e0e3ec",surfMax:"#d9dce5",surfMin:"#ffffff",on:"#1a1c20",onVar:"#44474f",out:"#74777f",outVar:"#c4c6d0",shad:"rgba(0,0,0,0.08)",scrim:"rgba(0,0,0,0.4)",ok:"#005a2f",okC:"#6ee09a",warn:"#7c5800",warnC:"#ffdea6"};
const trUpper=s=>s.replace(/i/g,"İ").replace(/ı/g,"I").toUpperCase();
const F=`'Inter','Segoe UI','Roboto',-apple-system,sans-serif`;
const DL=[{key:"beklemede",label:"Yapılacak",color:C.warn,bg:C.warnC,Ic:Clock},{key:"isleniyor",label:"İşleme Alındı",color:C.pri,bg:C.priC,Ic:RotateCw},{key:"tamamlandi",label:"Tamamlandı",color:C.ok,bg:C.okC,Ic:CheckCircle2}];
const DM=Object.fromEntries(DL.map(d=>[d.key,d]));

function fmtTarih(d){if(!d)return "";const dt=typeof d==="string"?new Date(d):d;const gg=String(dt.getDate()).padStart(2,"0");const aa=String(dt.getMonth()+1).padStart(2,"0");const yy=dt.getFullYear();const ss=String(dt.getHours()).padStart(2,"0");const dk=String(dt.getMinutes()).padStart(2,"0");return `${gg}.${aa}.${yy} ${ss}:${dk}`;}
function simdiTarih(){return fmtTarih(new Date());}
function fmtTutar(v){if(!v&&v!==0)return"";const n=parseFloat(String(v).replace(/[^\d.,-]/g,"").replace(",","."));if(isNaN(n))return String(v);return n.toLocaleString("tr-TR",{minimumFractionDigits:2,maximumFractionDigits:2});}
function fmtTarihDeger(v){if(!v)return"";if(/^\d{4}-\d{2}-\d{2}/.test(v)){const p=v.split("-");return p[2]+"."+p[1]+"."+p[0];}return v;}

let _toasts=[],_toastSubs=[],_toastTap=null;
const notifyToast=()=>_toastSubs.forEach(fn=>fn([..._toasts]));
function useToasts(){const[t,sT]=useState(_toasts);useEffect(()=>{const h=x=>sT(x);_toastSubs.push(h);return()=>{_toastSubs=_toastSubs.filter(x=>x!==h);};},[]);return t;}
function showToast(mesaj,tip="info",talepId=null){_toasts.unshift({id:Date.now()+Math.random(),mesaj,tip,ts:Date.now(),talepId});notifyToast();setTimeout(()=>{_toasts=_toasts.filter(t=>Date.now()-t.ts<4000);notifyToast();},4500);}
function useDB(){const[d,sD]=useState(()=>getDB());const vRef=useRef(0);useEffect(()=>{const unsub=subscribe(snap=>{const v=snap._v||0;if(v!==vRef.current){vRef.current=v;sD(snap);}});return unsub;},[]);return d;}

/* ═ mut() — SADECE local state günceller, Supabase'e YAZMAZ ═ */
import { supabase } from "./lib/supabase";

const mut = (fn) => {
  const db = getDB();
  fn(db);
  notify();
};

/* Talep değişikliklerini Supabase'e yazan helper */
async function syncTalep(id) {
  const db = getDB();
  const t = db.talepler.find(x => x.id === id);
  if (!t) return;
  if (typeof t.id === 'string' && t.id.startsWith('t')) {
    const row = {
      firma_id: (t.firmaId && t.firmaId !== 'genel') ? t.firmaId : null,
      olusturan_id: t.odId || t.olusturanId || null, olusturan: t.olusturan || 'office',
      atanan_id: t.atananId || null, kisi: t.kisi || null,
      sablon_id: t.sablonId || null, sablon_ad: t.sablonAd || '',
      alanlar: t.alanlar || [], durum: t.durum || 'beklemede',
      acil: t.acil || false, aciklama: t.aciklama || null,
      mukellef_gorsun: t.mukellefGorsun !== false, bildirim_gonder: t.bildirimGonder !== false,
      musavir_not: t.musavirNot || null, musavir_checkler: t.musavirCheckler || [],
      sonuclar: t.sonuclar || [], arsiv: t.arsiv || false,
    };
    const { data, error } = await supabase.from('talepler').insert(row).select().single();
    if (error) console.error('[SYNC] INSERT talep ERROR:', error);
    if (data) { const i = db.talepler.findIndex(x => x.id === id); if (i >= 0) { db.talepler[i] = { ...db.talepler[i], id: data.id }; notify(); } }
  } else {
    const row = { durum: t.durum, sablon_ad: t.sablonAd, mukellef_gorsun: t.mukellefGorsun !== false, bildirim_gonder: t.bildirimGonder !== false, musavir_not: t.musavirNot || null, musavir_checkler: t.musavirCheckler || [], sonuclar: t.sonuclar || [], atanan_id: t.atananId || null, acil: t.acil || false, aciklama: t.aciklama || null, kisi: t.kisi || null, arsiv: t.arsiv || false, alanlar: t.alanlar || [] };
    const { error } = await supabase.from('talepler').update(row).eq('id', t.id);
    if (error) console.error('[SYNC] UPDATE talep ERROR:', error);
  }
}

async function syncBildirim(b) {
  const row = { tip: b.tip, mesaj: b.mesaj, hedef: b.hedef, firma_id: b.firmaId || null, talep_id: b.talepId || null, okundu: b.okundu || false };
  await supabase.from('bildirimler').insert(row);
}

async function syncFirmaInsert(f) {
  const { data, error } = await supabase.from('firmalar').insert({ ad: f.ad, vkn: f.vkn || null, office_user_id: f.officeUserId }).select().single();
  if (error) console.error('[SYNC] INSERT firma ERROR:', error);
  if (data) { const db = getDB(); const i = db.firmalar.findIndex(x => x.id === f.id); if (i >= 0) { db.firmalar[i].id = data.id; notify(); } }
}

async function syncSablonSave(s, isNew) {
  const row = { ad: s.ad, alanlar: s.alanlar || [], kontrol_sablonu: s.kontrolSablonu || [], aciklama_sablonu: s.aciklamaSablonu || '', bildirim_sablonu: s.bildirimSablonu || '', baslik_format: s.baslikFormat, baslik_sep: s.baslikSep, office_user_id: s.officeUserId, sadece_musavir: s.sadeceMusavir || false };
  if (isNew) {
    const { data, error } = await supabase.from('sablonlar').insert(row).select().single();
    if (error) console.error('[SYNC] INSERT sablon ERROR:', error);
    if (data) { const db = getDB(); const i = db.sablonlar.findIndex(x => x.id === s.id); if (i >= 0) { db.sablonlar[i].id = data.id; notify(); } }
  } else {
    await supabase.from('sablonlar').update(row).eq('id', s.id);
  }
}

function buildBaslik(t,db){const sab=db.sablonlar.find(s=>s.id===t.sablonId);const fmt=sab?.baslikFormat||db.baslikFormat||["firmaAd","sablonAd"];const sep=sab?.baslikSep||db.baslikSep||" ";const f=db.firmalar.find(x=>x.id===t.firmaId);return fmt.map(k=>{if(k==="firmaAd")return f?.ad||"";if(k==="kisi")return t.kisi||"";if(k==="sablonAd")return t.sablonAd||"";if(k.startsWith("alan_")){const aId=k.replace("alan_","");const alan=t.alanlar?.find(a=>a.id===aId);if(alan&&alan.deger){if(alan.tip==="onay")return alan.deger?alan.ad:"";if(alan.tip==="dosya")return alan.deger?.name||"";return String(alan.deger);}return "";}return "";}).filter(Boolean).join(sep);}

/* ═ UI Kit ═ */
const Ic=({icon:I,size=20,color=C.onVar,style:s})=> <I size={size} color={color} strokeWidth={1.8} style={{flexShrink:0,...s}}/>;
const Btn=({children,onClick,disabled,vari="filled",color,full,sx})=>{const bg=vari==="filled"?(disabled?C.surfMax:(color||C.pri)):vari==="tonal"?(color||C.secC):"transparent";const fg=vari==="filled"?(disabled?C.onVar:C.onPri):vari==="tonal"?C.onSecC:(color||C.pri);return <button onClick={disabled?undefined:onClick} style={{display:"inline-flex",alignItems:"center",justifyContent:"center",gap:6,padding:"0 20px",minHeight:44,borderRadius:22,border:"none",background:bg,color:fg,fontSize:13,fontWeight:600,fontFamily:F,cursor:disabled?"default":"pointer",width:full?"100%":"auto",opacity:disabled?0.4:1,...sx}}>{children}</button>;};
function TF({label,value,onChange,type="text",focused,onFocus,onBlur,multiline}){const has=value&&value.length>0;const s={width:"100%",boxSizing:"border-box",padding:"18px 14px 6px",borderRadius:"4px 4px 0 0",border:"none",borderBottom:`2px solid ${focused?C.pri:C.out}`,background:C.surfMax,color:C.on,fontSize:14,fontFamily:F,outline:"none"};return <div style={{position:"relative",marginBottom:14}}><label style={{position:"absolute",left:14,zIndex:1,top:(focused||has)?5:14,fontSize:(focused||has)?10:14,color:focused?C.pri:C.onVar,transition:"all 150ms",fontFamily:F,pointerEvents:"none"}}>{label}</label>{multiline? <textarea value={value} onChange={e=>onChange(e.target.value)} onFocus={onFocus} onBlur={onBlur} rows={3} style={{...s,resize:"vertical"}}/>: <input type={type} value={value} onChange={e=>onChange(e.target.value)} onFocus={onFocus} onBlur={onBlur} style={s}/>}</div>;}
function Sheet({title,onClose,children}){const ref=useRef(null);const mounted=useRef(false);const dragRef=useRef({y:0,dy:0,dragging:false});useEffect(()=>{if(!mounted.current&&ref.current){ref.current.style.animation="sdUp 220ms ease-out";mounted.current=true;}});const onP=e=>{dragRef.current={y:e.clientY,dy:0,dragging:true};if(ref.current)ref.current.style.transition="none";};const onM=e=>{if(!dragRef.current.dragging)return;const dy=Math.max(0,e.clientY-dragRef.current.y);dragRef.current.dy=dy;if(ref.current)ref.current.style.transform=`translateY(${dy}px)`;};const onU=()=>{if(!dragRef.current.dragging)return;dragRef.current.dragging=false;if(dragRef.current.dy>120){if(ref.current){ref.current.style.transition="transform 200ms ease-in";ref.current.style.transform="translateY(100%)";setTimeout(onClose,210);}return;}if(ref.current){ref.current.style.transition="transform 250ms cubic-bezier(0.2,0,0,1)";ref.current.style.transform="";}};return <div style={{position:"fixed",inset:0,background:C.scrim,zIndex:300,display:"flex",alignItems:"flex-end",justifyContent:"center"}} onClick={onClose}><div ref={ref} style={{background:C.surfLow,borderRadius:"22px 22px 0 0",padding:"0 20px 28px",width:"100%",maxWidth:480,maxHeight:"88vh",overflowY:"auto"}} onClick={e=>e.stopPropagation()}><div onPointerDown={onP} onPointerMove={onM} onPointerUp={onU} style={{touchAction:"none",cursor:"grab",padding:"10px 0 14px",display:"flex",justifyContent:"center"}}><div style={{width:32,height:4,borderRadius:2,background:C.outVar}}/></div>{title&& <h2 style={{fontSize:17,fontWeight:600,color:C.on,fontFamily:F,margin:"0 0 14px"}}>{title}</h2>}{children}</div></div>;}
function Onay({mesaj,onEvet,onHayir,evetLabel}){return <div style={{position:"fixed",inset:0,background:C.scrim,zIndex:400,display:"flex",alignItems:"center",justifyContent:"center"}} onClick={onHayir}><div onClick={e=>e.stopPropagation()} style={{background:C.surfLow,borderRadius:20,padding:24,width:"calc(100% - 48px)",maxWidth:320}}><p style={{fontSize:14,color:C.onVar,fontFamily:F,margin:"0 0 20px",lineHeight:1.5}}>{mesaj}</p><div style={{display:"flex",gap:8,justifyContent:"flex-end"}}><Btn vari="text" onClick={onHayir}>Vazgeç</Btn><Btn onClick={onEvet}>{evetLabel||"Evet, Gönder"}</Btn></div></div></div>;}
const SB=({d,size=22})=>{const x=DM[d];if(!x)return null;return <div style={{width:size,height:size,borderRadius:"50%",background:x.bg,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,border:`1.5px solid ${x.color}`}}><Ic icon={x.Ic} size={size-8} color={x.color}/></div>;};
function Sel({label,value,onChange,options}){return <div style={{marginBottom:14}}><label style={{fontSize:13,fontWeight:600,color:C.onVar,fontFamily:F,display:"block",marginBottom:5}}>{label}</label><select value={value} onChange={e=>onChange(e.target.value)} style={{width:"100%",boxSizing:"border-box",padding:"10px 12px",borderRadius:"4px 4px 0 0",border:"none",borderBottom:`1px solid ${C.out}`,background:C.surfMax,color:C.on,fontSize:14,fontFamily:F,outline:"none"}}><option value="">Seçiniz...</option>{options.map((o,i)=> <option key={i} value={o.v}>{o.l}</option>)}</select></div>;}
const Empty=({icon:I,title,sub})=> <div style={{textAlign:"center",padding:"30px 16px"}}><Ic icon={I} size={40} color={C.outVar} style={{margin:"0 auto 8px",display:"block"}}/><div style={{fontSize:14,fontWeight:500,color:C.onVar,fontFamily:F}}>{title}</div>{sub&& <div style={{fontSize:12,color:C.out,fontFamily:F,marginTop:3}}>{sub}</div>}</div>;
const Chip=({label,active,onClick})=> <button onClick={onClick} style={{display:"inline-flex",alignItems:"center",gap:4,padding:"4px 12px",borderRadius:8,height:38,border:active?"none":`1px solid ${C.out}`,background:active?C.secC:"transparent",color:active?C.onSecC:C.onVar,fontSize:12,fontWeight:500,fontFamily:F,cursor:"pointer",whiteSpace:"nowrap"}}>{active&& <Ic icon={Check} size={13} color={C.onSecC}/>}{label}</button>;
const Stat=({icon:I,num,label,color})=> <div style={{flex:1,background:C.surfLow,borderRadius:12,padding:"14px 8px",textAlign:"center",border:`1px solid ${C.outVar}`}}><div style={{fontSize:20,fontWeight:700,color:C.on,fontFamily:F}}>{num}</div><div style={{display:"flex",alignItems:"center",justifyContent:"center",gap:4,marginTop:3}}><Ic icon={I} size={12} color={color}/><span style={{fontSize:11,color:C.onVar,fontWeight:600,fontFamily:F}}>{trUpper(label)}</span></div></div>;
const ST=({children})=> <div style={{fontSize:12,fontWeight:700,color:C.onVar,fontFamily:F,letterSpacing:0.5,marginBottom:8}}>{typeof children==="string"?trUpper(children):children}</div>;
function DosyaEkle({label,value,onChange,zorunlu}){return <div style={{marginBottom:6}}><div style={{fontSize:13,color:C.onVar,marginBottom:3,display:"flex",alignItems:"center",gap:3}}><Ic icon={Paperclip} size={11} color={C.onVar}/>{label}{zorunlu&& <span style={{color:C.err}}> *</span>}</div>{value? <div style={{display:"flex",alignItems:"center",gap:8,padding:"8px 10px",background:C.okC,borderRadius:8}}><Ic icon={File} size={16} color={C.ok}/><div style={{flex:1,fontSize:12,fontWeight:500,color:C.on}}>{value.name||value.ad||"Dosya"}</div><button onClick={()=>onChange(null)} style={{background:"none",border:"none",cursor:"pointer",padding:2}}><Ic icon={Trash2} size={14} color={C.err}/></button></div>: <div style={{display:"flex",gap:6}}><label style={{flex:1,display:"flex",alignItems:"center",justifyContent:"center",gap:5,padding:"10px 8px",borderRadius:8,border:`2px dashed ${C.outVar}`,background:C.surfMin,cursor:"pointer"}}><Ic icon={Upload} size={14} color={C.pri}/><span style={{fontSize:12,fontWeight:500,color:C.pri,fontFamily:F}}>Dosya Seç</span><input type="file" accept="image/*,application/pdf,.xml,.xlsx,.xls,.csv,.doc,.docx,.txt" onChange={e=>{if(e.target.files?.[0])onChange(e.target.files[0]);}} style={{display:"none"}}/></label><label style={{display:"flex",alignItems:"center",justifyContent:"center",gap:5,padding:"10px 12px",borderRadius:8,border:`2px dashed ${C.outVar}`,background:C.surfMin,cursor:"pointer"}}><Ic icon={Camera} size={14} color={C.pri}/><input type="file" accept="image/*" capture="environment" onChange={e=>{if(e.target.files?.[0])onChange(e.target.files[0]);}} style={{display:"none"}}/></label></div>}</div>;}

/* ═ Hamburger Menü — ORTADA, ALTTAN YUKARIYA ═ */
function Drawer({onClose,items,active,user,firmAd}){
  return <div style={{position:"fixed",inset:0,zIndex:250,background:C.scrim,backdropFilter:"blur(4px)"}} onClick={onClose}>
    <div style={{position:"absolute",bottom:0,left:0,right:0,margin:"0 auto",width:"94%",maxWidth:440,maxHeight:"50vh",background:C.surfMin,borderRadius:"22px 22px 0 0",boxShadow:"0 -8px 40px rgba(0,0,0,0.2)",animation:"menuUp 250ms ease-out",overflow:"auto"}} onClick={e=>e.stopPropagation()}>
      <div style={{display:"flex",justifyContent:"center",padding:"10px 0 6px"}}><div style={{width:36,height:4,borderRadius:2,background:C.outVar}}/></div>
      <div style={{padding:"4px 20px 24px"}}>
        <div style={{display:"flex",alignItems:"center",gap:10,padding:"12px 14px",background:C.surfLow,borderRadius:14,border:`1px solid ${C.outVar}`,marginBottom:14}}>
          <div style={{width:36,height:36,borderRadius:10,background:C.pri,display:"flex",alignItems:"center",justifyContent:"center"}}><Ic icon={Shield} size={16} color={C.onPri}/></div>
          <div><div style={{fontSize:14,fontWeight:700,color:C.on}}>{firmAd||"Mono Capital"}</div><div style={{fontSize:13,color:C.onVar}}>{user?.ad||""}</div></div>
        </div>
        {items.filter(i=>i.id!=="cikis").map(item=> <button key={item.id} onClick={()=>{item.onClick();onClose();}} style={{display:"flex",alignItems:"center",gap:14,padding:"13px 14px",width:"100%",borderRadius:12,border:"none",background:active===item.id?C.priC:"transparent",cursor:"pointer",fontFamily:F,textAlign:"left",marginBottom:2}}>
          <Ic icon={item.icon} size={20} color={active===item.id?C.pri:C.onVar}/>
          <span style={{fontSize:14,fontWeight:active===item.id?600:400,color:active===item.id?C.pri:C.on}}>{item.label}</span>
        </button>)}
        <div style={{borderTop:`1px solid ${C.outVar}`,marginTop:10,paddingTop:10}}>
          <button onClick={()=>{items.find(i=>i.id==="cikis")?.onClick();onClose();}} style={{display:"flex",alignItems:"center",gap:14,padding:"13px 14px",width:"100%",borderRadius:12,border:"none",background:"transparent",cursor:"pointer",fontFamily:F,textAlign:"left"}}>
            <Ic icon={LogOut} size={20} color={C.err}/><span style={{fontSize:14,fontWeight:500,color:C.err}}>Çıkış Yap</span>
          </button>
        </div>
      </div>
    </div>
  </div>;
}

/* ═ Alt Menü — Görevler, Kanban, Talepler ═ */
function BottomNav({a,onChange}){
  const items=[{id:"gorevler",icon:ClipboardList,label:"Görevler"},{id:"kanban",icon:LayoutDashboard,label:"Kanban"},{id:"talepler",icon:List,label:"Talepler"}];
  return <nav style={{position:"sticky",bottom:0,display:"flex",justifyContent:"space-around",background:C.surfCont,minHeight:60,paddingBottom:"env(safe-area-inset-bottom,0px)",alignItems:"center",zIndex:100,borderTop:`1px solid ${C.outVar}`}}>{items.map(o=> <button key={o.id} onClick={()=>onChange(o.id)} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:2,border:"none",background:"none",cursor:"pointer",padding:"0 24px",fontFamily:F}}>
    <div style={{width:52,height:42,borderRadius:14,display:"flex",alignItems:"center",justifyContent:"center",background:a===o.id?C.secC:"transparent"}}><Ic icon={o.icon} size={20} color={a===o.id?C.onSecC:C.onVar}/></div>
    <span style={{fontSize:12,fontWeight:a===o.id?600:400,color:a===o.id?C.onSecC:C.onVar}}>{o.label}</span>
  </button>)}</nav>;
}

/* ═ KARŞILAMA ═ */
function DosyaOnizle({dosya,onClose}){if(!dosya)return null;const ext=(dosya.ad||"").split(".").pop().toLowerCase();const isImg=["jpg","jpeg","png","gif","webp","svg"].includes(ext);const isPdf=ext==="pdf";const url=dosya.publicUrl||dosya.data||"";return <div style={{position:"fixed",inset:0,background:C.scrim,zIndex:350,display:"flex",flexDirection:"column"}} onClick={onClose}><div style={{display:"flex",alignItems:"center",gap:10,padding:"12px 16px",background:C.surfLow}} onClick={e=>e.stopPropagation()}><button onClick={onClose} style={{background:"none",border:"none",cursor:"pointer",padding:2}}><Ic icon={ArrowLeft} size={20} color={C.on}/></button><div style={{flex:1,minWidth:0}}><div style={{fontSize:14,fontWeight:600,color:C.on,wordBreak:"break-word"}}>{dosya.ad}</div><div style={{fontSize:12,color:C.out}}>{dosya.boyut||""} — {dosya.tarih}</div></div>{url&&<a href={url} download={dosya.ad} onClick={e=>e.stopPropagation()} style={{padding:"6px 12px",borderRadius:8,background:C.pri,color:C.onPri,fontSize:13,fontWeight:600,fontFamily:F,textDecoration:"none",display:"flex",alignItems:"center",gap:4}}><Ic icon={Download} size={13} color={C.onPri}/> İndir</a>}</div><div style={{flex:1,overflow:"auto",display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={e=>e.stopPropagation()}>{url?isImg?<img src={url} style={{maxWidth:"100%",maxHeight:"100%",borderRadius:12,objectFit:"contain"}}/>:isPdf?<iframe src={url} style={{width:"100%",height:"100%",border:"none",borderRadius:12}}/>:<div style={{textAlign:"center"}}><Ic icon={File} size={48} color={C.pri}/><div style={{fontSize:14,fontWeight:500,color:C.on,marginTop:12}}>{dosya.ad}</div><div style={{fontSize:12,color:C.out,marginTop:4}}>Bu dosya türü önizlenemez</div><a href={url} download={dosya.ad} style={{display:"inline-flex",alignItems:"center",gap:6,marginTop:16,padding:"10px 20px",borderRadius:22,background:C.pri,color:C.onPri,fontSize:13,fontWeight:600,fontFamily:F,textDecoration:"none"}}><Ic icon={Download} size={14} color={C.onPri}/> Dosyayı İndir</a></div>:<div style={{textAlign:"center"}}><Ic icon={File} size={48} color={C.out}/><div style={{fontSize:13,color:C.out,marginTop:8}}>Önizleme mevcut değil</div></div>}</div></div>;}

function ToastBar(){const toasts=useToasts();if(toasts.length===0)return null;return <div style={{position:"fixed",top:0,left:0,right:0,zIndex:500,display:"flex",flexDirection:"column",alignItems:"center",padding:"env(safe-area-inset-top,8px) 12px 0",pointerEvents:"none"}}>{toasts.slice(0,3).map((t,i)=>{const renk=t.tip==="ok"?C.ok:t.tip==="err"?C.err:C.pri;const ikon=t.tip==="ok"?CheckCircle2:t.tip==="err"?AlertCircle:Bell;return <div key={t.id} onClick={()=>{if(t.talepId&&_toastTap)_toastTap(t.talepId);_toasts=_toasts.filter(x=>x.id!==t.id);notifyToast();}} style={{background:C.surfMin,borderRadius:16,padding:"12px 16px",marginBottom:6,boxShadow:"0 6px 24px rgba(0,0,0,0.18)",border:`1px solid ${renk}44`,display:"flex",alignItems:"center",gap:10,maxWidth:420,width:"100%",animation:"toastIn 300ms ease-out",pointerEvents:"auto",cursor:"pointer"}}><div style={{width:32,height:32,borderRadius:10,background:renk+"18",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}><Ic icon={ikon} size={16} color={renk}/></div><div style={{flex:1,minWidth:0}}><div style={{fontSize:13,fontWeight:600,color:C.on,fontFamily:F,wordBreak:"break-word",lineHeight:1.3}}>{t.mesaj}</div></div></div>;})}</div>;}

function Karsilama({onSec}){return <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",background:`linear-gradient(160deg,${C.surf} 0%,#c5cae9 100%)`}}><div style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:24}}><div style={{width:80,height:80,borderRadius:20,background:C.pri,display:"flex",alignItems:"center",justifyContent:"center",marginBottom:20,boxShadow:"0 6px 24px rgba(13,71,161,0.35)"}}><Ic icon={Shield} size={38} color={C.onPri}/></div><h1 style={{fontSize:26,fontWeight:800,color:C.on,fontFamily:F,margin:"0 0 4px"}}>Mono Capital</h1><p style={{fontSize:13,color:C.onVar,fontFamily:F,margin:0,textAlign:"center",maxWidth:260}}>Mükellef talep yönetimi ve görev takip platformu</p></div><div style={{padding:"0 24px 40px",display:"flex",flexDirection:"column",gap:12,maxWidth:400,width:"100%",margin:"0 auto"}}><button onClick={()=>onSec("client")} style={{display:"flex",alignItems:"center",gap:14,padding:"16px 20px",borderRadius:16,border:`1px solid ${C.outVar}`,background:C.surfMin,cursor:"pointer",fontFamily:F}}><div style={{width:48,height:48,borderRadius:14,background:C.priC,display:"flex",alignItems:"center",justifyContent:"center"}}><Ic icon={User} size={22} color={C.pri}/></div><div style={{flex:1,textAlign:"left"}}><div style={{fontSize:15,fontWeight:600,color:C.on}}>Mükellef Girişi</div><div style={{fontSize:13,color:C.onVar,marginTop:2}}>İşlem yapabileceğiniz firmalar</div></div><Ic icon={ChevronRight} size={18} color={C.outVar}/></button><button onClick={()=>onSec("office")} style={{display:"flex",alignItems:"center",gap:14,padding:"16px 20px",borderRadius:16,border:"none",background:C.pri,cursor:"pointer",fontFamily:F,boxShadow:"0 2px 12px rgba(13,71,161,0.3)"}}><div style={{width:48,height:48,borderRadius:14,background:"rgba(255,255,255,0.15)",display:"flex",alignItems:"center",justifyContent:"center"}}><Ic icon={Briefcase} size={22} color={C.onPri}/></div><div style={{flex:1,textAlign:"left"}}><div style={{fontSize:15,fontWeight:600,color:C.onPri}}>Müşavir Girişi</div><div style={{fontSize:13,color:"rgba(255,255,255,0.7)",marginTop:2}}>Müşavir paneli</div></div><Ic icon={ChevronRight} size={18} color="rgba(255,255,255,0.4)"/></button></div></div>;}

/* ═ GİRİŞLER ═ */
function ClientLogin({onLogin,onBack}){const db=useDB();const[ep,sE]=useState("");const[pw,sP]=useState("");const[bh,sBH]=useState(false);const[foc,sF]=useState("");const[err,sErr]=useState("");const go=()=>{const k=db.firma_kullanici.find(x=>x.eposta===ep&&(x.sifre===pw||(x.geciciSifre===pw&&x.ilkGiris)));if(k){if(bh)try{localStorage.setItem("mc_user",JSON.stringify({...k,rol:"client"}))}catch{}onLogin({...k,rol:"client"});}else sErr("E-posta veya şifre hatalı");};return <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",justifyContent:"center",alignItems:"center",padding:20,background:C.surf}}><button onClick={onBack} style={{position:"absolute",top:16,left:16,background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",gap:4,color:C.pri,fontSize:13,fontFamily:F,fontWeight:600}}><Ic icon={ArrowLeft} size={18} color={C.pri}/> Geri</button><Ic icon={User} size={40} color={C.pri} style={{marginBottom:14}}/><h1 style={{fontSize:22,fontWeight:700,color:C.on,fontFamily:F,margin:"0 0 24px"}}>Mükellef Girişi</h1><div style={{width:"100%",maxWidth:320,background:C.surfLow,borderRadius:20,padding:20}}><TF label="E-posta" value={ep} onChange={sE} type="email" focused={foc==="e"} onFocus={()=>sF("e")} onBlur={()=>sF("")}/><TF label="Şifre" value={pw} onChange={sP} type="password" focused={foc==="p"} onFocus={()=>sF("p")} onBlur={()=>sF("")}/>{err&& <div style={{display:"flex",alignItems:"center",gap:5,color:C.err,fontSize:12,fontFamily:F,marginBottom:8}}><Ic icon={AlertCircle} size={14} color={C.err}/>{err}</div>}<label onClick={()=>sBH(p=>!p)} style={{display:"flex",alignItems:"center",gap:8,marginBottom:12,cursor:"pointer"}}><div style={{width:20,height:20,borderRadius:5,background:bh?C.pri:"transparent",border:`2px solid ${bh?C.pri:C.out}`,display:"flex",alignItems:"center",justifyContent:"center"}}>{bh&&<Ic icon={Check} size={10} color={C.onPri}/>}</div><span style={{fontSize:12,color:C.onVar,fontFamily:F}}>Beni Hatırla</span></label><Btn onClick={go} full sx={{height:42,borderRadius:21,fontSize:14}}>Giriş Yap</Btn></div></div>;}

function OfficeLogin({onLogin,onBack}){const db=useDB();const[mod,sM]=useState("giris");const[ep,sE]=useState("");const[pw,sP]=useState("");const[pw2,sP2]=useState("");const[ad,sA]=useState("");const[fa,sFA]=useState("");const[foc,sF]=useState("");const[err,sErr]=useState("");const[bh2,sBH2]=useState(false);
  const giris=()=>{const m=db.ekip.find(x=>x.eposta===ep&&x.sifre===pw);if(m){if(bh2)try{localStorage.setItem("mc_user",JSON.stringify({...m,rol:"office"}))}catch{}onLogin({...m,rol:"office"});}else sErr("E-posta veya şifre hatalı");};
  const kayit=()=>{if(!ad.trim()||!ep.trim()||!pw||!fa.trim()){sErr("Tüm alanları doldurunuz");return;}if(pw!==pw2){sErr("Şifreler eşleşmiyor");return;}if(pw.length<4){sErr("Şifre en az 4 karakter");return;}if(db.ekip.find(x=>x.eposta===ep.trim())){sErr("Bu e-posta zaten kayıtlı");return;}const uid="ou"+Date.now();mut(d=>{d.ekip.push({id:uid,ad:ad.trim(),eposta:ep.trim(),sifre:pw,anaFirma:fa.trim(),rol:"admin"});});onLogin({id:uid,ad:ad.trim(),eposta:ep.trim(),anaFirma:fa.trim(),rol:"office"});};
  return <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",justifyContent:"center",alignItems:"center",padding:20,background:C.surf}}><button onClick={onBack} style={{position:"absolute",top:16,left:16,background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",gap:4,color:C.pri,fontSize:13,fontFamily:F,fontWeight:600}}><Ic icon={ArrowLeft} size={18} color={C.pri}/> Geri</button><Ic icon={Briefcase} size={40} color={C.pri} style={{marginBottom:14}}/><h1 style={{fontSize:22,fontWeight:700,color:C.on,fontFamily:F,margin:"0 0 24px"}}>{mod==="giris"?"Müşavir Girişi":"Müşavir Kaydı"}</h1><div style={{width:"100%",maxWidth:320,background:C.surfLow,borderRadius:20,padding:20}}>{mod==="kayit"&& <TF label="Ad Soyad" value={ad} onChange={sA} focused={foc==="a"} onFocus={()=>sF("a")} onBlur={()=>sF("")}/>}{mod==="kayit"&& <TF label="Firma Adınız" value={fa} onChange={sFA} focused={foc==="f"} onFocus={()=>sF("f")} onBlur={()=>sF("")}/>}<TF label="E-posta" value={ep} onChange={sE} type="email" focused={foc==="e"} onFocus={()=>sF("e")} onBlur={()=>sF("")}/><TF label="Şifre" value={pw} onChange={sP} type="password" focused={foc==="p"} onFocus={()=>sF("p")} onBlur={()=>sF("")}/>{mod==="kayit"&& <TF label="Şifre Tekrar" value={pw2} onChange={sP2} type="password" focused={foc==="2"} onFocus={()=>sF("2")} onBlur={()=>sF("")}/>}{err&& <div style={{display:"flex",alignItems:"center",gap:5,color:C.err,fontSize:12,fontFamily:F,marginBottom:8}}><Ic icon={AlertCircle} size={14} color={C.err}/>{err}</div>}{mod==="giris"&&<label onClick={()=>sBH2(p=>!p)} style={{display:"flex",alignItems:"center",gap:8,marginBottom:12,cursor:"pointer"}}><div style={{width:20,height:20,borderRadius:5,background:bh2?C.pri:"transparent",border:`2px solid ${bh2?C.pri:C.out}`,display:"flex",alignItems:"center",justifyContent:"center"}}>{bh2&&<Ic icon={Check} size={10} color={C.onPri}/>}</div><span style={{fontSize:12,color:C.onVar,fontFamily:F}}>Beni Hatırla</span></label>}<Btn onClick={mod==="giris"?giris:kayit} full sx={{height:42,borderRadius:21,fontSize:14}}>{mod==="giris"?"Giriş Yap":"Kayıt Ol"}</Btn><div style={{textAlign:"center",marginTop:14}}><button onClick={()=>{sM(mod==="giris"?"kayit":"giris");sErr("");}} style={{background:"none",border:"none",color:C.pri,fontSize:12,fontFamily:F,cursor:"pointer",fontWeight:600}}>{mod==="giris"?"Hesabınız yok mu? Kaydolun":"Zaten hesabınız var mı? Giriş"}</button></div></div></div>;}

function IlkGiris({user,onDone}){const[s1,sS1]=useState("");const[s2,sS2]=useState("");const[foc,sF]=useState("");const[err,sErr]=useState("");const go=()=>{if(s1.length<4){sErr("En az 4 karakter");return;}if(s1!==s2){sErr("Şifreler eşleşmiyor");return;}mut(d=>{const k=d.firma_kullanici.find(x=>x.id===user.id);if(k){k.sifre=s1;k.ilkGiris=false;k.geciciSifre=null;}});onDone({...user,sifre:s1,ilkGiris:false});};return <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",justifyContent:"center",alignItems:"center",padding:20,background:C.surf}}><Ic icon={Lock} size={40} color={C.pri} style={{marginBottom:14}}/><h1 style={{fontSize:18,fontWeight:600,color:C.on,fontFamily:F,margin:"0 0 20px"}}>Hoş Geldiniz! Yeni şifrenizi belirleyin</h1><div style={{width:"100%",maxWidth:320,background:C.surfLow,borderRadius:20,padding:20}}><TF label="Yeni Şifre" value={s1} onChange={sS1} type="password" focused={foc==="a"} onFocus={()=>sF("a")} onBlur={()=>sF("")}/><TF label="Şifre Tekrar" value={s2} onChange={sS2} type="password" focused={foc==="b"} onFocus={()=>sF("b")} onBlur={()=>sF("")}/>{err&& <div style={{color:C.err,fontSize:12,fontFamily:F,marginBottom:8}}>{err}</div>}<Btn onClick={go} full sx={{height:42,borderRadius:21}}>Şifreyi Belirle</Btn></div></div>;}

function FirmaSecim({user,firmalar,onSec,onCikis}){return <div style={{minHeight:"100vh",display:"flex",flexDirection:"column",background:C.surf,maxWidth:480,margin:"0 auto"}}><div style={{padding:"20px 16px 10px",display:"flex",justifyContent:"space-between",alignItems:"center"}}><div><div style={{fontSize:12,color:C.onVar}}>Merhaba</div><div style={{fontSize:20,fontWeight:700,color:C.on,fontFamily:F}}>{user.ad}</div></div><Btn vari="text" onClick={onCikis} color={C.err} sx={{fontSize:13}}><Ic icon={LogOut} size={14} color={C.err}/></Btn></div><div style={{padding:"10px 16px 0"}}><ST>İşlem Yapabileceğiniz Firmalar</ST></div><div style={{flex:1,padding:"8px 16px",overflow:"auto"}}>{firmalar.length===0? <Empty icon={Building2} title="Henüz atanmış firma yok" sub="Müşaviriniz sizi firmaya ekleyecektir"/>:firmalar.map(f=> <button key={f.id} onClick={()=>onSec(f)} style={{display:"flex",alignItems:"center",gap:14,padding:"16px",borderRadius:14,border:`1px solid ${C.outVar}`,background:C.surfMin,cursor:"pointer",fontFamily:F,width:"100%",marginBottom:8,textAlign:"left"}}><div style={{width:44,height:44,borderRadius:12,background:C.priC,display:"flex",alignItems:"center",justifyContent:"center"}}><Ic icon={Building2} size={20} color={C.pri}/></div><div style={{flex:1}}><div style={{fontSize:15,fontWeight:600,color:C.on}}>{f.ad}</div>{f.vkn&& <div style={{fontSize:13,color:C.onVar}}>VKN: {f.vkn}</div>}</div><Ic icon={ChevronRight} size={20} color={C.outVar}/></button>)}</div></div>;}

