      {drawerPage==="ayarlar"&& <div style={{padding:14}}><div style={{display:"flex",alignItems:"center",gap:6,marginBottom:12}}><button onClick={()=>sDrPage(null)} style={{background:"none",border:"none",cursor:"pointer",padding:2}}><Ic icon={ArrowLeft} size={18} color={C.pri}/></button><h1 style={{fontSize:18,fontWeight:700,color:C.on,margin:0}}>Ayarlar</h1></div><ST>Bildirimler</ST><label onClick={()=>mut(d=>{if(!d.bildirimAyar)d.bildirimAyar={office:true,client:true};d.bildirimAyar.office=!d.bildirimAyar.office;})} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 14px",background:C.surfMin,borderRadius:12,cursor:"pointer",border:`1px solid ${C.outVar}`}}><div style={{width:24,height:24,borderRadius:7,background:db.mpirofil?.office?C.pri:"transparent",border:`2px solid ${db.mpirofil?.office?C.pri:C.out}`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{db.mpirofil?.office&&<Ic icon={Check} size={11} color={C.onPri}/>}</div><div style={{flex:1}}><div style={{fontSize:13,fontWeight:500,color:C.on,fontFamily:F}}>Bildirimler</div><div style={{fontSize:12,color:C.out}}>Yeni talep geldiğinde bildirim al</div></div></label></div>}

      {drawerPage==="arsiv"&& <div style={{padding:14}}><div style={{display:"flex",alignItems:"center",gap:6,marginBottom:12}}><button onClick={()=>sDrPage(null)} style={{background:"none",border:"none",cursor:"pointer",padding:2}}><Ic icon={ArrowLeft} size={18} color={C.pri}/></button><h1 style={{fontSize:18,fontWeight:700,color:C.on,margin:0}}>Arşiv</h1></div>{arsivTalepler.length===0?<Empty icon={Archive} title="Arşiv boş"/>:arsivTalepler.map(t=>{const f=db.firmalar.find(x=>x.id===t.firmaId);const baslik=buildBaslik(t,db);return <div key={t.id} style={{display:"flex",alignItems:"center",gap:10,background:C.surfMin,borderRadius:12,padding:"12px 14px",marginBottom:5,border:`1px solid ${C.outVar}`}}><SB d={t.durum}/><div style={{flex:1,minWidth:0}}><div style={{fontSize:13,fontWeight:600,color:C.on,wordBreak:"break-word",lineHeight:1.3}}>{baslik||t.sablonAd}</div><div style={{fontSize:12,color:C.out,marginTop:2}}>{f?.ad||"Genel"}</div></div><button onClick={()=>{updateTalep(t.id,{arsiv:false});}} style={{padding:"4px 10px",borderRadius:6,border:"none",background:C.priC,cursor:"pointer",fontSize:13,fontWeight:600,color:C.pri,fontFamily:F}}>Geri Al</button></div>;})}</div>}

