    {/* FAB */}
    {!drawerPage&& <button onClick={()=>sSh("oyt")} style={{position:"fixed",bottom:"calc(68px + env(safe-area-inset-bottom,0px))",right:"max(14px, calc(50% - 226px))",display:"flex",alignItems:"center",gap:6,height:44,padding:"0 16px 0 12px",borderRadius:12,border:"none",background:C.pri,color:C.onPri,fontSize:13,fontWeight:600,fontFamily:F,cursor:"pointer",boxShadow:"0 2px 12px rgba(13,71,161,0.3)",zIndex:50}}><Ic icon={Edit3} size={16} color={C.onPri}/>  Yeni Görev</button>}

